import * as THREE from './vendor/three.module.js';
import {createH13} from './h13-adapter.js';
import {ExperienceMixer} from './audio.js';
import {SPHERES,createState,enterRoom,selectNext,shotAt,rng} from './state.js';
import {createRelief} from './private/relief-r3.js';
import {createKfbEye} from './kfb-eye.js';
const $=id=>document.getElementById(id),state=createState(),mixer=new ExperienceMixer();
const metrics={revision:'hypernorm-scenelet-r2',frames:0,elapsed:0,rooms:[],holds:[],errors:[],fps:0,videoTextures:1,renderer:'three',h13Source:'46670cfa5c62c3aea6aa3840d301fc7a35723407',mixer:'WebAudio music/atmo/voice, one AudioContext'};
const recipes=await Promise.all(SPHERES.map(id=>fetch('./recipes/'+id+'.json').then(r=>r.json())));
mixer.recipes=recipes;
const memes=await fetch('./private/meme-pool.json').then(r=>r.json());recipes[0].texts=memes.pool.filter(x=>x.kind==='slogan'&&x.faction==='blob').slice(0,12).map(x=>x.text);
if(!recipes[0].texts.length)recipes[0].texts=memes.pool.filter(x=>x.text).slice(0,12).map(x=>x.text);
const canvas=$('world'),renderer=new THREE.WebGLRenderer({canvas,antialias:true,powerPreference:'high-performance',preserveDrawingBuffer:true});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.outputColorSpace=THREE.SRGBColorSpace;
const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(72,1,.05,100);camera.rotation.order='YXZ';
const collage=document.createElement('canvas'),h13=await createH13(collage,recipes,memes),map=new THREE.CanvasTexture(collage);map.colorSpace=THREE.SRGBColorSpace;
const surface=new THREE.Mesh(new THREE.SphereGeometry(25,64,40),new THREE.MeshBasicMaterial({map,side:THREE.BackSide,color:0x8a9687}));scene.add(surface);
const lookUniform={value:0},timeUniform={value:0};
surface.material.onBeforeCompile=shader=>{shader.uniforms.uLook=lookUniform;shader.uniforms.uTime=timeUniform;shader.fragmentShader='uniform float uLook; uniform float uTime;\n'+shader.fragmentShader;shader.fragmentShader=shader.fragmentShader.replace('#include <dithering_fragment>',`#include <dithering_fragment>
float lum=dot(gl_FragColor.rgb,vec3(.299,.587,.114));
if(uLook<.5){float scan=.82+.18*sin(gl_FragCoord.y*3.14159);gl_FragColor.rgb=mix(gl_FragColor.rgb,vec3(.19,.53,.25)*lum*2.,.68)*scan;}
else if(uLook<1.5){vec2 grid=mod(gl_FragCoord.xy,6.)-3.;float paper=step(length(grid),lum*3.8);gl_FragColor.rgb=mix(vec3(.08,.07,.04),vec3(.67,.62,.43),paper);}
else{gl_FragColor.rgb=mix(gl_FragColor.rgb,vec3(.52,.26,.46)*(.35+lum),.35);}
gl_FragColor.rgb*=.985+.015*sin(uTime*2.);`);};
const shells=[];
for(let i=0;i<3;i++){const mesh=new THREE.Mesh(new THREE.SphereGeometry(11+i*3.4,40,24),new THREE.MeshBasicMaterial({map,side:THREE.BackSide,transparent:true,opacity:.06+i*.025,depthWrite:false,blending:THREE.AdditiveBlending}));mesh.rotation.set(.16*i,.65*i,.08*i);shells.push(mesh);scene.add(mesh);}
const objects=new THREE.Group();scene.add(objects);
const geometry=new THREE.SphereGeometry(.45,36,24);
const pearl=new THREE.Mesh(new THREE.SphereGeometry(1.7,64,40),new THREE.MeshBasicMaterial({map,color:0xbbe790}));pearl.position.set(0,0,-5);scene.add(pearl);
const pearlHalo=new THREE.Mesh(new THREE.SphereGeometry(1.85,32,20),new THREE.MeshBasicMaterial({color:0xa7e574,transparent:true,opacity:.08,side:THREE.BackSide}));pearl.add(pearlHalo);
const video=document.createElement('video');video.playsInline=true;video.preload='auto';video.loop=false;video.crossOrigin='anonymous';video.src='./private/bnwn01/bnwn01_001.mp4';
const vt=new THREE.VideoTexture(video);vt.colorSpace=THREE.SRGBColorSpace;
const television=new THREE.Group();const cabinet=new THREE.Mesh(new THREE.BoxGeometry(2.6,1.9,.7),new THREE.MeshBasicMaterial({color:0x181c19}));cabinet.rotation.z=-.07;television.add(cabinet);
const tube=new THREE.Mesh(new THREE.PlaneGeometry(2.26,1.45),new THREE.MeshBasicMaterial({map:vt}));tube.position.z=.37;television.add(tube);television.position.set(-3.6,.6,-6);television.rotation.y=.33;objects.add(television);
const {group:eye,target:pupil,rig:eyeRig}=createKfbEye();eye.position.set(4,.4,-5);objects.add(eye);scene.add(new THREE.HemisphereLight(0xffffff,0x604224,2.5));
const bubbles=[];for(let i=0;i<2;i++){const bubble=new THREE.Mesh(geometry,new THREE.MeshBasicMaterial({map,transparent:true,opacity:.85,color:i?0xddbbea:0xc0f4a6}));bubble.position.set(i?-5:2.5,i?2.1:-.8,i?1:-8);objects.add(bubble);bubbles.push(bubble);}
const door=new THREE.Group();for(const [x,y,w,h] of [[-.65,0,.04,2.4],[.65,0,.04,2.4],[0,1.2,1.35,.04]]){const line=new THREE.Mesh(new THREE.PlaneGeometry(w,h),new THREE.MeshBasicMaterial({color:0xe8cc7f}));line.position.set(x,y,0);door.add(line);}door.position.set(1.5,.2,5);door.rotation.y=Math.PI;objects.add(door);
let relief=null;try{relief=createRelief(renderer);objects.add(relief.object);}catch(e){metrics.errors.push('R3: '+e.message);}
const raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2(),keys=new Set(),clock=new THREE.Clock();
let running=false,yaw=0,pitch=0,drag=null,started=0,lastFrame=performance.now(),frameWindow=0,frameCount=0,steer=0,clipIndex=0,lastDraw=0,holdSlot=-1,transitionTimer=null;
objects.visible=false;camera.position.set(0,0,0);
const resize=()=>{renderer.setSize(innerWidth,innerHeight,false);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();};addEventListener('resize',resize);resize();
const showError=e=>{metrics.errors.push(e.message||String(e));$('error').hidden=false;$('error').textContent='Experience: '+(e.message||e);};
video.addEventListener('error',()=>showError(Error('BNWN source unavailable')));
video.addEventListener('ended',()=>{clipIndex=(clipIndex+13)%69;const file='bnwn01/bnwn01_'+String(clipIndex+1).padStart(3,'0')+'.mp4';video.src='./private/'+file;mixer.voiceClip(file).catch(showError);video.play().catch(showError);});
let stutter=0,stutterTimer=0;
video.addEventListener('timeupdate',()=>{if(state.room!==1||!running)return;if(video.currentTime>stutter+.45){video.pause();clearTimeout(stutterTimer);stutterTimer=setTimeout(()=>{if(state.room!==1)return;video.currentTime=stutter;video.play().catch(showError);stutter=(stutter+.31)%Math.max(1,video.duration-1);},160);}});
function applyRoom(index){const recipe=recipes[index];lookUniform.value=index;enterRoom(state,index,state.elapsed);metrics.rooms.push({id:recipe.id,time:state.elapsed,visit:state.visits[index]});h13.setRoom(recipe,state.seed+state.visits[index]*997);surface.material.color.set(index===2?'#b195be':'#8a9687');scene.background=new THREE.Color(recipe.colors[0]);television.visible=index===0;door.visible=index===1;if(relief)relief.object.visible=index===2;eye.visible=true;camera.position.set(0,0,0);yaw=0;pitch=0;stutter=video.currentTime;clearTimeout(stutterTimer);$('place').textContent=recipe.title.toUpperCase();holdSlot=-1;if(index<2)video.play().catch(showError);else video.pause();}
async function transition(index){if(state.transitioning||!running)return;state.transitioning=true;try{await mixer.prepare(recipes[index]);await mixer.change(recipes[index]);/* J-cut: next audio begins 6 frames at 25fps before picture. */transitionTimer=setTimeout(()=>{$('veil').classList.add('cut');setTimeout(()=>{applyRoom(index);$('veil').classList.remove('cut');state.transitioning=false;},180);},240);}catch(e){state.transitioning=false;showError(e);}}
function mode(value){state.mode=value;$('mode').textContent=value==='auto'?'Autopilot':'Rabbit-Hole';if(value==='rabbit')state.lastInput=state.elapsed;}
function input(){if(!running)return;if(state.mode==='auto'&&!keys.has('arrowleft')&&!keys.has('arrowright'))mode('rabbit');state.lastInput=state.elapsed;}
$('enter').onclick=async()=>{try{$('enter').disabled=true;await mixer.start();mixer.attachVideo(video);await mixer.voiceClip('bnwn01/bnwn01_001.mp4');await mixer.change(recipes[0]);running=true;started=performance.now();state.lastInput=0;applyRoom(0);objects.visible=true;pearl.visible=false;pearlHalo.visible=false;$('entry').style.display='none';canvas.focus();}catch(e){$('enter').disabled=false;showError(e);}};
$('mode').onclick=()=>mode(state.mode==='auto'?'rabbit':'auto');$('home').onclick=()=>transition(0);$('mute').onclick=()=>{$('mute').textContent=mixer.toggleMute()?'Muted':'Sound on';};$('volume').oninput=e=>mixer.setVolume(+e.target.value);
$('headphones').onclick=e=>{const on=e.currentTarget.getAttribute('aria-pressed')!=='true';e.currentTarget.setAttribute('aria-pressed',String(on));mixer.headphones(on);};
addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();const key=e.key.toLowerCase();if(key==='m'){mode(state.mode==='auto'?'rabbit':'auto');return;}if(key==='escape'){transition(0);return;}keys.add(key);steer=key==='arrowleft'||key==='a'?-1:key==='arrowright'||key==='d'?1:steer;input();});addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
canvas.addEventListener('pointerdown',e=>{drag={x:e.clientX,y:e.clientY,moved:false};canvas.setPointerCapture(e.pointerId);input();});
canvas.addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;drag.moved||=Math.abs(dx)+Math.abs(dy)>3;yaw-=dx*.004;pitch=Math.max(-1.25,Math.min(1.25,pitch-dy*.004));steer=Math.sign(dx);drag.x=e.clientX;drag.y=e.clientY;input();});
canvas.addEventListener('pointerup',e=>{if(drag&&!drag.moved&&running){pointer.set(e.clientX/innerWidth*2-1,-e.clientY/innerHeight*2+1);raycaster.setFromCamera(pointer,camera);const candidates=[tube,pupil,...bubbles,...door.children];const hit=raycaster.intersectObjects(candidates)[0];if(hit){const kind=hit.object===tube?'television':hit.object===pupil?'eye':bubbles.includes(hit.object)?'bubble':'door';const target=recipes[state.room].portals.find(p=>p.kind===kind);if(target)transition(SPHERES.indexOf(target.target));}else if(relief&&state.room===2)relief.kick();}drag=null;});
$('wordPortal').onclick=()=>{const portal=recipes[state.room].portals.find(p=>p.kind==='caption');if(portal)transition(SPHERES.indexOf(portal.target));};
$('evidence').onclick=()=>{$('evidencePanel').hidden=false;};$('closeEvidence').onclick=()=>{$('evidencePanel').hidden=true;};
let isolation=false;$('source').onclick=()=>{isolation=!isolation;surface.visible=!isolation;for(const s of shells)s.visible=!isolation;objects.visible=!isolation;pearl.visible=isolation;pearl.position.set(0,0,-4);$('source').textContent=isolation?'Return to world':'Source isolation';};
async function record(modeName){if(!running)return;mode(modeName);$('recordAuto').disabled=true;$('recordRabbit').disabled=true;$('recordStatus').textContent='Recording 60 seconds with mixer audio…';const stream=canvas.captureStream(25);for(const track of mixer.capture.stream.getAudioTracks())stream.addTrack(track);const recorder=new MediaRecorder(stream,{mimeType:MediaRecorder.isTypeSupported('video/webm;codecs=vp9,opus')?'video/webm;codecs=vp9,opus':'video/webm',videoBitsPerSecond:3500000});const chunks=[];recorder.ondataavailable=e=>chunks.push(e.data);recorder.onstop=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(chunks,{type:'video/webm'}));a.download='hypernorm-r2-'+modeName+'-'+Date.now()+'.webm';a.textContent='Download 60s '+modeName+' with sound';a.id='download-'+modeName;$('recordStatus').replaceChildren(a);$('recordAuto').disabled=false;$('recordRabbit').disabled=false;};recorder.start(1000);setTimeout(()=>recorder.stop(),60000);}
$('recordAuto').onclick=()=>record('auto');$('recordRabbit').onclick=()=>record('rabbit');
function frame(now){requestAnimationFrame(frame);const dt=Math.min(.05,(now-lastFrame)/1000);lastFrame=now;frameCount++;if(now-frameWindow>1000){metrics.fps=Math.round(frameCount*1000/(now-frameWindow));frameCount=0;frameWindow=now;}if(running){state.elapsed=(now-started)/1000;if(state.mode==='rabbit'&&state.elapsed-state.lastInput>=20)mode('auto');const local=state.elapsed-state.roomStarted,slot=shotAt(local);if(slot.hold&&slot.slot!==holdSlot){metrics.holds.push({room:SPHERES[state.room],at:state.elapsed,duration:slot.duration});holdSlot=slot.slot;}if(now-lastDraw>1000/15){try{h13.paint(local,slot);map.needsUpdate=true;}catch(e){if(!metrics.errors.includes(e.message))showError(e);}lastDraw=now;}
 if(state.mode==='auto'){yaw+=dt*.065;pitch=Math.sin(local*.15)*.16;camera.position.set(Math.sin(local*.13)*1.1,Math.sin(local*.19)*.35,Math.cos(local*.13)*.6);if(local>25&&!state.transitioning){transition(selectNext(state,steer));steer=0;}}else{const speed=dt*2.5,forward=new THREE.Vector3(-Math.sin(yaw),0,-Math.cos(yaw)),right=new THREE.Vector3(Math.cos(yaw),0,-Math.sin(yaw));if(keys.has('w')||keys.has('arrowup'))camera.position.addScaledVector(forward,speed);if(keys.has('s')||keys.has('arrowdown'))camera.position.addScaledVector(forward,-speed);if(keys.has('a')||keys.has('arrowleft'))camera.position.addScaledVector(right,-speed);if(keys.has('d')||keys.has('arrowright'))camera.position.addScaledVector(right,speed);if(keys.size)input();if(camera.position.length()>8)camera.position.setLength(8);for(const bubble of bubbles)if(camera.position.distanceTo(bubble.position)<.7)transition(selectNext(state));}
 camera.rotation.set(pitch,yaw,0);eye.lookAt(camera.position);television.rotation.z=Math.sin(local*.3)*.025;for(let i=0;i<shells.length;i++)shells[i].rotation.y+=dt*.004*(i%2?-1:1);if(relief&&state.room===2)relief.update(dt);
 const line=recipes[state.room].texts[Math.floor(local/7)%recipes[state.room].texts.length];$('caption').textContent=line;const listener=mixer.context?.listener;if(listener){listener.positionX.value=camera.position.x;listener.positionY.value=camera.position.y;listener.positionZ.value=camera.position.z;listener.forwardX.value=-Math.sin(yaw);listener.forwardZ.value=-Math.cos(yaw);}
 }else{pearl.rotation.y+=dt*.09;const x=collage.getContext('2d');x.fillStyle='#1c3023';x.fillRect(0,0,1024,512);x.strokeStyle='#a8db76';for(let i=0;i<28;i++){x.beginPath();x.ellipse(512,256,50+i*14,20+i*8,now*.00008+i*.04,0,Math.PI*2);x.stroke();}map.needsUpdate=true;}
 eyeRig.update(dt);mixer.updateVoice();timeUniform.value=state.elapsed;renderer.render(scene,camera);metrics.frames++;metrics.elapsed=state.elapsed;metrics.audio=mixer.level();metrics.visits=state.visits;metrics.activeRoom=SPHERES[state.room];metrics.mode=state.mode;metrics.h13Sources=h13.sourceCount;metrics.audioState=mixer.context?.state||'not-started';metrics.errors=[...new Set(metrics.errors)];$('metrics').textContent=JSON.stringify(metrics,null,2);canvas.dataset.metrics=JSON.stringify(metrics);
}
$('enter').disabled=false;$('enter').textContent='Enter with sound ↗';
frame(performance.now());addEventListener('pagehide',()=>{clearTimeout(transitionTimer);video.pause();mixer.dispose();relief?.dispose();renderer.dispose();});
